    // 万一还有"找不到悬浮球"的情况，这一行就能直接说明它到底跑去了哪里。
    const 指纹 = `${viewport.left},${viewport.top},${viewport.width},${viewport.height}|${位置.left},${位置.top}|${Math.round(rect.left)},${Math.round(rect.top)}`;
