    const topbar = root.querySelector('.shell-topbar');
    if (topbar) {
      setImportant(topbar, { 'flex-wrap': 'nowrap', 'overflow-x': 'auto', 'align-items': 'center' });
    }
    const close = root.querySelector('.shell-close');
    if (close) {
      setImportant(close, {
        'flex-shrink': '0',
        'min-width': '30px',
        'min-height': '30px',
        'margin-left': 'auto',
      });
    }
